'use client';
import {useEffect,useRef,useState} from 'react';
import {useClientReady} from '@/lib/client-ready';
import {hotelRpc,type Room} from '@/lib/pilot';
import {definitiveBookingRejection} from '@/lib/pending-booking';
import {isTurnoverUuid,isTurnoverVersion} from '@/lib/turnovers';

type Command={request:string;version:number;status:'Clean'|'Dirty'|'Inspect'};
type Result={request_id:string;replayed:boolean;room:{id:string;tenant_id:string;property_id:string;state_version:number;housekeeping:string}};
type Props={tenant:string;property:string;actor:string;room:Room;occupied:boolean;disabled:boolean;onBusyChange:(busy:boolean)=>void;onSaved:()=>Promise<void>};
function validCommand(value:unknown):value is Command{if(!value||typeof value!=='object'||Array.isArray(value))return false;const command=value as Command;return Object.keys(command).sort().join(',')==='request,status,version'&&isTurnoverUuid(command.request)&&isTurnoverVersion(command.version)&&['Clean','Dirty','Inspect'].includes(command.status)}
function validateResult(result:Result,command:Command,tenant:string,property:string,room:string){if(!result||result.request_id!==command.request||typeof result.replayed!=='boolean'||result.room?.id!==room||result.room.tenant_id!==tenant||result.room.property_id!==property||result.room.housekeeping!==command.status||!isTurnoverVersion(result.room.state_version)||result.room.state_version<command.version||result.room.state_version>command.version+1)throw Error('The saved readiness receipt does not match this room request. Keep the exact request for reconciliation.')}
export function RoomReadiness(props:Props){return useClientReady()?<ReadinessForm key={props.actor+':'+props.tenant+':'+props.property+':'+props.room.id} {...props}/>:<output>Loading saved requests…</output>}
function ReadinessForm({tenant,property,actor,room,occupied,disabled,onBusyChange,onSaved}:Props){
 const key='iratepilot-pms-pending-readiness:'+actor+':'+tenant+':'+property+':'+room.id;
 const [restored]=useState(()=>{try{const raw=sessionStorage.getItem(key);if(raw===null)return {pending:null,error:''};const command:unknown=JSON.parse(raw);if(!validCommand(command))throw Error();return {pending:command,error:''}}catch{return {pending:null,error:'The saved room update could not be read. Resolve it before changing readiness.'}}});
 const [pending,setPending]=useState<Command|null>(restored.pending),[error,setError]=useState(restored.error),[notice,setNotice]=useState(''),[refreshRequired,setRefreshRequired]=useState(false),[busy,setBusy]=useState(false),[reviewedContext,setReviewedContext]=useState<string|null>(null),lock=useRef(false),alive=useRef(true),callbacks=useRef({onBusyChange,onSaved});
 useEffect(()=>{callbacks.current={onBusyChange,onSaved}},[onBusyChange,onSaved]);
 useEffect(()=>{alive.current=true;const cleanup=()=>{alive.current=false;if(lock.current)callbacks.current.onBusyChange(false)};return()=>cleanup()},[]);
 async function post(command:Command){if(disabled||lock.current||restored.error)return;const recovering=pending!==null;lock.current=true;setBusy(true);callbacks.current.onBusyChange(true);setError('');setNotice('');
  try{if(!validCommand(command))throw Error('The saved room request is invalid.');sessionStorage.setItem(key,JSON.stringify(command));setPending(command);const result=await hotelRpc<Result>('set_housekeeping',{p_tenant:tenant,p_property:property,p_room:room.id,p_request:command.request,p_expected_version:command.version,p_status:command.status});validateResult(result,command,tenant,property,room.id);if(alive.current){sessionStorage.removeItem(key);setPending(null);setReviewedContext(null);setNotice(recovering?'Saved readiness receipt confirmed. Current room status is reloaded separately.':occupied?'Dirty status recorded. The guest remains assigned; no vacant-room task was dispatched.':'Dirty status recorded. Vacant-room preparation work is queued or restarted.');try{await callbacks.current.onSaved()}catch{setError('Room update saved. Refresh the workspace before another update.');setRefreshRequired(true)}}}
  catch(e){if(alive.current){if(definitiveBookingRejection(e)){if(!recovering||(e as {code?:string}).code==='PT409'){sessionStorage.removeItem(key);setPending(null);setReviewedContext(null)}else setNotice('The earlier readiness request remains unresolved. Retry its exact identity to recover an existing receipt; current room status alone does not prove its outcome.');try{await callbacks.current.onSaved()}catch{setRefreshRequired(true)}setError(e instanceof Error?e.message:'Room state changed. Refresh before trying again.')}else setError('The readiness result is uncertain or its receipt did not match. Retry the saved request to confirm its recorded result.')}}
  finally{lock.current=false;if(alive.current){setBusy(false);callbacks.current.onBusyChange(false)}}
 }
 async function refresh(){if(disabled||lock.current)return;lock.current=true;setBusy(true);callbacks.current.onBusyChange(true);try{await callbacks.current.onSaved();if(alive.current){setRefreshRequired(false);setError(restored.error)}}catch{if(alive.current)setError('Hotel data could not refresh. Try again.')}finally{lock.current=false;if(alive.current){setBusy(false);callbacks.current.onBusyChange(false)}}}
 const reviewContext=room.state_version+'/'+occupied+'/'+room.status,reviewed=reviewedContext===reviewContext;
 const blocked=busy||disabled||!!restored.error||refreshRequired;
 return <>{error&&<p className="pilot-error" role="alert">{error}</p>}{notice&&<output className="pilot-notice">{notice}</output>}{refreshRequired&&<button className="secondary" disabled={busy||disabled} onClick={()=>void refresh()}>Refresh room controls</button>}
 {pending?<div><p>Pending readiness update: {pending.status}</p><p>Older Clean/Inspect commands can only recover their original receipt. New readiness promotions use the turnover task and manager inspection.</p><button className="secondary" disabled={blocked} onClick={()=>void post(pending)}>Retry saved room update</button></div>:<form key={room.state_version+'/'+occupied} onSubmit={event=>{event.preventDefault();if(!reviewed)return;void post({request:crypto.randomUUID(),version:room.state_version,status:'Dirty'})}}><p>Current readiness: <b>{room.status}</b>. Clean and Inspect require the turnover workflow.</p><label className="pilot-check"><input type="checkbox" required checked={reviewed} onChange={event=>setReviewedContext(event.target.checked?reviewContext:null)} disabled={blocked}/>I reviewed this room and am ready to mark it Dirty.{occupied?' The guest remains assigned; this will not dispatch vacant-room work.':' This queues preparation or restarts open work and invalidates previous cleaning approval.'}</label><button className="secondary" disabled={blocked||!reviewed}>Mark Dirty for preparation</button></form>}
 <a className="text-button" href="#turnover-work">Open turnover tasks and inspection</a></>;
}
